const parts = String(msg.topic || '').split('/');
const mqttId = parts[1];
if (!mqttId) return null;
const keys = JSON.parse(env.get('DEVICE_API_KEYS') || '{}');
const deviceKey = keys[mqttId];
if (!deviceKey) {
  node.warn('Sin DEVICE_API_KEYS para ' + mqttId);
  return null;
}
const payload = typeof msg.payload === 'object' ? msg.payload : {};
payload.mqttId = mqttId;
msg.headers = {
  'Content-Type': 'application/json',
  'X-Ingest-Token': env.get('INGEST_TOKEN'),
  'X-Device-Key': deviceKey
};
msg.url = (env.get('API_URL') || 'http://api:3000') + '/api/ingest/telemetry';
msg.payload = payload;
msg.mqttId = mqttId;
return msg;

const parts = String(msg.topic || '').split('/');
const mqttId = parts[1];
const keys = JSON.parse(env.get('DEVICE_API_KEYS') || '{}');
const deviceKey = keys[mqttId];
if (!deviceKey) return null;
const status = String(msg.payload || '').trim();
msg.headers = {
  'Content-Type': 'application/json',
  'X-Ingest-Token': env.get('INGEST_TOKEN'),
  'X-Device-Key': deviceKey
};
msg.url = (env.get('API_URL') || 'http://api:3000') + '/api/ingest/status';
msg.payload = { mqttId, status };
return msg;

const parts = String(msg.topic || '').split('/');
const mqttId = parts[1];
const keys = JSON.parse(env.get('DEVICE_API_KEYS') || '{}');
const deviceKey = keys[mqttId];
if (!deviceKey) return null;
const payload = typeof msg.payload === 'object' ? msg.payload : {};
payload.mqttId = mqttId;
msg.headers = {
  'Content-Type': 'application/json',
  'X-Ingest-Token': env.get('INGEST_TOKEN'),
  'X-Device-Key': deviceKey
};
msg.url = (env.get('API_URL') || 'http://api:3000') + '/api/ingest/event';
msg.payload = payload;
return msg;

const body = msg.payload || {};
const mqttId = msg.mqttId;
if (!mqttId) return null;
if (body.regar === true) {
  msg.topic = 'hidrobot/' + mqttId + '/comando';
  msg.payload = { accion: 'regar', segundos: body.segundos || 0 };
  msg.qos = 1;
  msg.retain = false;
  return msg;
}
if (body.regar === false && body.motivo && String(body.motivo).includes('detener')) {
  msg.topic = 'hidrobot/' + mqttId + '/comando';
  msg.payload = { accion: 'detener' };
  msg.qos = 1;
  msg.retain = false;
  return msg;
}
return null;

const parts = String(msg.topic || '').split('/');
const mqttId = parts[1];
if (!mqttId) return null;
const keys = JSON.parse(env.get('DEVICE_API_KEYS') || '{}');
const deviceKey = keys[mqttId];
if (!deviceKey) {
  node.warn('Sin DEVICE_API_KEYS para ' + mqttId);
  return null;
}
msg.headers = {
  'Content-Type': 'application/json',
  'X-Ingest-Token': env.get('INGEST_TOKEN'),
  'X-Device-Key': deviceKey
};
msg.url = (env.get('API_URL') || 'http://api:3000') + '/api/ingest/config/request';
msg.payload = { mqttId };
msg.mqttId = mqttId;
node.log('ESP solicita config: ' + mqttId);
return msg;

const keys = JSON.parse(env.get('DEVICE_API_KEYS') || '{}');
const ids = Object.keys(keys);
if (!ids.length) {
  node.warn('Sin DEVICE_API_KEYS: no se borra retain');
  return null;
}
node.log('Borrando retain de config para: ' + ids.join(', '));
return ids.map((mqttId) => ({
  topic: 'hidrobot/' + mqttId + '/config',
  payload: '',
  qos: 1,
  retain: true
}));

const token = (msg.req && msg.req.headers && (msg.req.headers['x-nodered-token'] || msg.req.headers['X-NodeRed-Token'])) || '';
if (!token || token !== env.get('NODERED_TOKEN')) {
  node.warn('hidrobot/publish: token inválido');
  msg.statusCode = 401;
  msg.payload = { error: 'unauthorized' };
  return [null, null, msg];
}
const body = msg.payload || {};
const mqttId = body.mqttId;
const kind = body.kind;
if (!mqttId || !kind) {
  msg.statusCode = 400;
  msg.payload = { error: 'mqttId y kind requeridos' };
  return [null, null, msg];
}
if (kind === 'comando') {
  msg.topic = 'hidrobot/' + mqttId + '/comando';
  msg.payload = body.payload || {};
  msg.qos = 1;
  msg.retain = false;
  msg._reply = { ok: true, kind: 'comando', topic: msg.topic };
  node.log('MQTT comando → ' + msg.topic);
  return [msg, null, null];
}
if (kind === 'config') {
  msg.topic = 'hidrobot/' + mqttId + '/config';
  msg.payload = body.payload || {};
  msg.qos = 1;
  msg.retain = false;
  msg._reply = { ok: true, kind: 'config', topic: msg.topic, retain: false };
  node.log('MQTT config → ' + msg.topic + ' ' + JSON.stringify(msg.payload));
  return [null, msg, null];
}
msg.statusCode = 400;
msg.payload = { error: 'kind inválido' };
return [null, null, msg];

msg.statusCode = 200;
msg.payload = msg._reply || { ok: true };
return msg;
